#!/bin/bash
# Parameter-reduced variants for NTS-KEM (NIST PQC Round 1, NTS-KEM(12,64)).
#
# Knob: the Goppa error-correction parameter T (correctable errors / Goppa
# degree). Full strength T=64; M=12 (GF(2^12), N=4096) held FIXED. Lower T =
# fewer errors = weaker (McEliece/NTS-KEM has ZERO decryption-failure rate, so
# round-trips are deterministic). All derived size constants are regenerated by
# variant_patches/patch_nts_kem.py from T (and the sibling api.h in lockstep).
#
#   hard   T=48  -> [4096,3520,97]
#   medium T=32  -> [4096,3712,65]
#   easy   T=16  -> [4096,3904,33]
#
# Concealment: the patcher lives in ./variant_patches/ at the algorithm ROOT
# (a sibling of environment/), so it never enters the Docker build context and
# the agent never sees it. The weakened source is repacked into the SAME archive
# name, so build_cli.sh stays byte-identical to the full-strength task.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"        # algorithm root
ALGORITHMS_DIR="$(dirname "$SCRIPT_DIR")"
ALGO_NAME="$(basename "$SCRIPT_DIR")"
SRC_REL="environment/algorithm_src"
ARCHIVE="NTS_KEM.zip"
# Path (inside the archive) to the params header build_cli.sh's nts_kem_12_64 uses.
PARAMS_REL="NTS-KEM/Reference_Implementation/kem/nts_kem_12_64/nts_kem_params.h"

# band|param-encoding|T
VARIANTS=(
    "easy|t16|16"
    "medium|t32|32"
    "hard|t48|48"
)

for entry in "${VARIANTS[@]}"; do
    IFS='|' read -r BAND ENC T <<< "$entry"
    VARIANT_DIR="$ALGORITHMS_DIR/${ALGO_NAME}_variant_${BAND}_${ENC}"

    rm -rf "$VARIANT_DIR"
    cp -r "$SCRIPT_DIR" "$VARIANT_DIR"
    rm -f  "$VARIANT_DIR/generate_variants.sh"

    ARCH="$VARIANT_DIR/$SRC_REL/$ARCHIVE"
    TMP="$(mktemp -d)"
    unzip -q -o "$ARCH" -d "$TMP"

    python3 "$SCRIPT_DIR/variant_patches/patch_nts_kem.py" "$TMP/$PARAMS_REL" "$T"

    # Repack into the SAME archive name (target is the VARIANT copy, never the
    # committed original), preserving the "NTS-KEM/..." internal layout.
    ( cd "$TMP" && rm -f "$ARCH" && zip -q -r -X "$ARCH" . )
    rm -rf "$TMP"

    # Drop the patcher from the shipped variant (it sits outside environment/
    # anyway, but keep the generated task folder clean).
    rm -rf "$VARIANT_DIR/variant_patches"
done
